package com.example.data

import android.content.Context
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONObject
import java.io.InputStream
import kotlin.math.ln

/**
 * The full text of Tawzih al-Masail (Urdu), bundled as assets/tauzih.json, plus an offline
 * keyword search over it. The JSON is generated by tools/build_book_json.py from the official
 * text at https://www.sistani.org/urdu/book/61/.
 */
object BookRepository {
    const val SOURCE_URL = "https://www.sistani.org/urdu/book/61/"

    @Volatile
    var isLoaded = false
        private set

    var chapters: List<Chapter> = emptyList()
        private set
    var items: List<Masla> = emptyList()
        private set

    private var normText: Array<String> = emptyArray()
    private var normHead: Array<String> = emptyArray()
    private var avgLength = 1.0
    private var byId: Map<String, Masla> = emptyMap()

    suspend fun ensureLoaded(context: Context) = withContext(Dispatchers.IO) {
        if (!isLoaded) context.assets.open("tauzih.json").use { load(it) }
    }

    @Synchronized
    fun load(input: InputStream) {
        if (isLoaded) return
        val root = JSONObject(input.bufferedReader(Charsets.UTF_8).readText())
        val chArr = root.getJSONArray("chapters")
        val ch = ArrayList<Chapter>(chArr.length())
        for (i in 0 until chArr.length()) {
            val o = chArr.getJSONObject(i)
            ch += Chapter(i, o.getString("title"), o.getString("url"), o.optInt("from", 0), o.optInt("to", 0))
        }
        val itArr = root.getJSONArray("items")
        val its = ArrayList<Masla>(itArr.length())
        for (i in 0 until itArr.length()) {
            val o = itArr.getJSONObject(i)
            its += Masla(i, o.getInt("n"), o.getInt("c"), o.optString("s"), o.getString("t"))
        }
        normText = Array(its.size) { TextNorm.normalize(its[it].text) }
        normHead = Array(its.size) { TextNorm.normalize(ch[its[it].chapter].title + " " + its[it].section) }
        avgLength = normText.sumOf { it.length }.toDouble() / normText.size.coerceAtLeast(1)
        byId = its.associateBy { it.id }
        chapters = ch
        items = its
        isLoaded = true
    }

    fun byId(id: String): Masla? = byId[id]

    fun byNumber(number: Int): Masla? = byId["M$number"]

    fun chapterOf(m: Masla): Chapter = chapters[m.chapter]

    fun chapterItems(chapter: Int): List<Masla> = items.filter { it.chapter == chapter }

    /**
     * Ranks book entries against a question. [query] may be in any of the app's languages;
     * known Roman Urdu / English / Persian / Arabic fiqh terms are mapped to their Urdu spelling.
     * [extraUrduTerms] are additional Urdu keywords (e.g. produced by the AI query rewriter).
     */
    fun search(query: String, extraUrduTerms: List<String> = emptyList(), limit: Int = 10): List<Masla> {
        if (!isLoaded) return emptyList()
        val terms = LinkedHashMap<String, Double>()
        fun add(raw: String, weight: Double) {
            val t = TextNorm.normalize(raw)
            if (t.length < 2 || t in TextNorm.stopWords) return
            terms[t] = maxOf(terms[t] ?: 0.0, weight)
        }
        val words = TextNorm.normalize(query).split(' ').filter { it.isNotBlank() }
        words.forEach { w ->
            add(w, 1.0)
            Glossary.lookup(w).forEach { add(it, 1.0) }
        }
        // Two-word phrases catch terms such as "family planning" or "post mortem".
        words.zipWithNext().forEach { (a, b) -> Glossary.lookup("$a $b").forEach { add(it, 1.2) } }
        extraUrduTerms.forEach { phrase ->
            add(phrase, 1.3)
            val parts = TextNorm.normalize(phrase).split(' ')
            if (parts.size > 1) parts.forEach { add(it, 0.6) }
        }
        if (terms.isEmpty()) return emptyList()

        val n = items.size
        val scores = DoubleArray(n)
        for ((term, weight) in terms) {
            val tf = IntArray(n)
            var df = 0
            for (i in 0 until n) {
                val c = countOccurrences(normText[i], term)
                tf[i] = c
                if (c > 0) df++
            }
            if (df == 0) continue
            val idf = ln(1.0 + (n - df + 0.5) / (df + 0.5))
            for (i in 0 until n) {
                var s = 0.0
                if (tf[i] > 0) {
                    val lengthNorm = 0.25 + 0.75 * normText[i].length / avgLength
                    s += idf * (tf[i] * 2.2) / (tf[i] + 1.2 * lengthNorm)
                }
                if (normHead[i].contains(term)) s += idf * 1.5
                scores[i] += s * weight
            }
        }
        return (0 until n).filter { scores[it] > 0.0 }
            .sortedByDescending { scores[it] }
            .take(limit)
            .map { items[it] }
    }

    private fun countOccurrences(text: String, term: String): Int {
        var count = 0
        var from = text.indexOf(term)
        while (from >= 0 && count < 8) {
            count++
            from = text.indexOf(term, from + term.length)
        }
        return count
    }
}

/** Script-insensitive normalisation shared by the index and the queries. */
object TextNorm {
    fun normalize(s: String): String {
        val sb = StringBuilder(s.length)
        var lastSpace = true
        for (ch in s) {
            val c: Char = when (ch) {
                in 'ً'..'ٟ', 'ٰ', in 'ۖ'..'ۭ', 'ـ', '‌', '‍', '‎', '‏' -> continue
                'ي', 'ى', 'ئ' -> 'ی'
                'ك' -> 'ک'
                'ه', 'ة', 'ۃ', 'ۂ', 'ۀ' -> 'ہ'
                'أ', 'إ', 'آ', 'ٱ' -> 'ا'
                'ؤ' -> 'و'
                'ۓ' -> 'ے'
                in '۰'..'۹' -> '0' + (ch - '۰')
                in '٠'..'٩' -> '0' + (ch - '٠')
                else -> if (ch.isLetterOrDigit()) ch.lowercaseChar() else ' '
            }
            if (c == ' ') {
                if (!lastSpace) sb.append(' ')
                lastSpace = true
            } else {
                sb.append(c)
                lastSpace = false
            }
        }
        return sb.toString().trim()
    }

    val stopWords: Set<String> = (
        "کے کی کا کو میں سے پر ہے ہیں اور یہ وہ کیا تو بھی نے ہو ہوں ہوا ہوتا ہوتی ہوتے گا گی گے کہ اگر جو اس ان ایک " +
            "نہیں نہ کر کرنا کرے کریں کرتا کرتی کیسے کب کیوں کون کس کسی لئے لیے بارے حکم مسئلہ مسائل تھا تھی جب تک ہی یا " +
            "است در به از که را با این آن چه چیست هل ما ماذا في من على عن هو هي الى " +
            "the is are a an of to in on for what how when why who which can i my me do does it and or if with be about " +
            "ruling rule rules masla masail hukm " +
            "ka ki ke ko me mein main mai se par pe hai hain he ho hota hoti aur ya kya kia kaise kese kab kyun kyu " +
            "to bhi nahi nahin na agar jo is us ye yeh wo woh ek kis kisi liye bare kar karna kare"
        ).split(' ').map { normalize(it) }.toSet()
}

